import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"遯","description":"周易集解 - 遯","frontmatter":{"title":"遯","description":"周易集解 - 遯"},"headers":[],"relativePath":"zh/classics/jijie/033.md","filePath":"zh/classics/jijie/033.md"}'),l={name:"zh/classics/jijie/033.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="遯" tabindex="-1">遯 <a class="header-anchor" href="#遯" aria-label="Permalink to “遯”">​</a></h1><h2 id="遯-1" tabindex="-1">遯 <a class="header-anchor" href="#遯-1" aria-label="Permalink to “遯”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>遯，亨。小利貞。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：物不可以久居其所，故受之以遯。遯者，退也。</p><p>韓康伯曰：夫婦之道，以恆為貴，而物之所居，不可以恆，宜與世升降，有時而遯者也。</p><p>虞翻曰：陰消姤二也。艮為山，巽為入，乾為遠，遠山入藏，故遯，以陰消陽，子弒其父，小人道長，避之乃通，故遯而通。則當位而應，與時行也。</p><p>虞翻曰：小，陰，謂二。得位浸長，以柔變剛，故小利貞。</p><p>鄭玄曰：遯，逃去之名也。艮為門闕。乾有健德。互體有巽，巽為進退。君子出門，行有進退，逃去之象。曰五得位而有應，是用正道得禮見召聘。始仕他國，當尚謙謙。小其和順之道，居小官，乾小事，其進以漸，則遠妒忌之害，昔陳敬仲奔齊辭卿是也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：遯亨，遯而亨也。剛當位而應，與時行也。遯之時義大矣哉。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>侯果曰：此本乾卦。陰長剛殞，君子遯避，遯則通也。</p><p>虞翻曰：剛謂五而應二，艮為時，故與時行矣。</p><p>荀爽曰：陰稱小，浸而長，則將消陽，故利正。居是與五相應也。</p><p>陸績曰：謂陽氣退，陰氣將害，隨時遯避，其義大矣。</p><p>宋衷曰：太公遯殷，四皓遯秦之時也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：天下有山，遯。君子以遠小人，不惡而嚴。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：天喻君子，山比小人。小人浸長，若山之侵天。君子遯避，若天之遠山，故言天下有山遯也。</p><p>虞翻曰：君子謂乾。乾為遠為嚴。小人謂陰。坤為惡，為小人。故｢以遠小人，不惡而嚴｣也。</p><p>侯果曰：群小浸盛，剛德殞削，故君子避之。高尚林野，但矜嚴於外，亦不憎惡於內，所謂吾家耄遜於荒也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，遯尾，厲，勿用有攸往。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>陸績曰：陰氣已至於二，而初在其後，故曰遯尾也。避難當在前，而在後，故厲。往則與災難會，故勿用有攸往。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：遯尾之厲，不往何災也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：艮為尾也。初失位，動而得正，故遯尾厲。之應成坎為災，在艮宜靜，若不往於四，則無災矣。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，執之用黃牛之革，莫之勝說。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：艮為手，稱執；否坤為黃牛；艮為皮。四變之初，則坎水濡皮。離日乾之，故｢執之用黃牛之革｣。莫，無也。勝，能。說，解也。乾為堅剛，巽為繩，艮為手，持革縛三在坎中，故莫之勝說也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：執用黃牛，固志也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：六二離爻，離為黃牛。體艮履正，上應貴主。志在輔時，不隨物遯。獨守中直，堅如革束。執此之志，莫之勝說。殷之父師，當此爻矣。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，係遯，有疾厲，畜臣妾吉。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：厲，危也。巽繩為係，四變三體坎，坎為疾。故有疾厲。遯陰剝陽，三消成坤，與上易位。坤為臣，兌為妾，上來之三，據坤應兌，故畜臣妾吉也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：係遯之厲，有疾憊也。畜臣妾吉，不可大事也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>王肅曰：三上係於二而獲遯，故曰係遯。病此係執而獲危懼，故曰有疾憊也。此於六二，畜臣妾之象。足以畜其臣妾，不可施為大事也。</p><p>虞翻曰：三動入坤，坤為事，故不可大事也。</p><p>荀爽曰：大事謂與五同任天下之政。潛遯之世，但可居家畜養臣妾，不可治國之大事。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，好遯，君子吉，小人否。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：否乾為好，為君子；陰稱小人。動之初，故君子吉。陰在四多懼，故小人否。得位承五，故無凶咎矣。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：君子好遯，小人否也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：不處其位，而遯於外，好遯者也。然有應在初，情未能棄。君子剛斷，故能舍之。小人係戀，必不能矣。故｢君子吉，小人凶｣矣。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，嘉遯，貞吉。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：乾為嘉，剛當位應二，故貞吉。謂三已變，上來之三，成坎象，故曰以正志也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：嘉遯貞吉，以正志也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：時否德剛，雖遯中正，嘉遯者也。故曰貞吉。遯而得正，則群小應命，所謂紐以紊之。剛正群小之志，則殷之高宗當此爻矣。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，肥遯，無不利。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：乾盈為肥。二不及上，故肥遯無不利。故《象》曰：｢無所疑也。｣</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：肥遯無不利，無所疑也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：最處外極，無應於內。心無疑戀，超世高舉。果行育德，安時無悶，遯之肥也。故曰｢肥遯無不利｣，則潁濱巢許當此爻矣。</p>',74)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
